using System;using System.Collections.ObjectModel;using System.Linq;using System.Threading;using System.Threading.Tasks;using System.Windows.Input;using Microsoft.Extensions.Logging;using PhotoBooth.Admin.UI.Mvvm;using PhotoBooth.Core.Models;using PhotoBooth.Core.Services;
namespace PhotoBooth.Admin.UI.ViewModels { public sealed class PresetManagerViewModel:PageViewModel { readonly IPresetService service;readonly ILogger<PresetManagerViewModel> log;Preset selected;string newName="New Preset",message;public PresetManagerViewModel(IPresetService s,ILogger<PresetManagerViewModel> l){service=s;log=l;CreateCommand=new AsyncCommand(_=>Create());DeleteCommand=new AsyncCommand(_=>Delete(),_=>SelectedPreset!=null);DuplicateCommand=new AsyncCommand(_=>Duplicate(),_=>SelectedPreset!=null);RenameCommand=new AsyncCommand(_=>Rename(),_=>SelectedPreset!=null);DefaultCommand=new AsyncCommand(_=>SetDefault(),_=>SelectedPreset!=null);_=Load();}public override string Title=>"Preset Manager";public ObservableCollection<Preset> Presets{get;}=new ObservableCollection<Preset>();public Preset SelectedPreset{get=>selected;set=>Set(ref selected,value);}public string NewName{get=>newName;set=>Set(ref newName,value);}public string Message{get=>message;set=>Set(ref message,value);}public ICommand CreateCommand{get;}public ICommand DeleteCommand{get;}public ICommand DuplicateCommand{get;}public ICommand RenameCommand{get;}public ICommand DefaultCommand{get;}async Task Load(){Presets.Clear();foreach(var x in await service.GetAllAsync(CancellationToken.None))Presets.Add(x);}async Task Create(){var now=DateTime.UtcNow;await service.SaveAsync(new Preset{Id=Guid.NewGuid(),Name=string.IsNullOrWhiteSpace(NewName)?"New Preset":NewName,CreatedAtUtc=now,ModifiedAtUtc=now,CaptureCountdownSeconds=3},CancellationToken.None);await Load();}async Task Delete(){await Guard(async()=>{await service.DeleteAsync(SelectedPreset.Id,CancellationToken.None);await Load();},"Delete failed");}async Task Duplicate(){await Guard(async()=>{var now=DateTime.UtcNow;var x=SelectedPreset;await service.SaveAsync(new Preset{Id=Guid.NewGuid(),Name=x.Name+" Copy",CreatedAtUtc=now,ModifiedAtUtc=now,FrameId=x.FrameId,PrinterProfileId=x.PrinterProfileId,CaptureCountdownSeconds=x.CaptureCountdownSeconds,SettingsJson=x.SettingsJson},CancellationToken.None);await Load();},"Duplicate failed");}async Task Rename(){await Guard(async()=>{SelectedPreset.Name=NewName;SelectedPreset.ModifiedAtUtc=DateTime.UtcNow;await service.SaveAsync(SelectedPreset,CancellationToken.None);await Load();},"Rename failed");}async Task SetDefault(){await Guard(async()=>{foreach(var x in Presets.Where(x=>x.IsDefault)){x.IsDefault=false;await service.SaveAsync(x,CancellationToken.None);}SelectedPreset.IsDefault=true;SelectedPreset.ModifiedAtUtc=DateTime.UtcNow;await service.SaveAsync(SelectedPreset,CancellationToken.None);await Load();},"Default preset could not be saved");}async Task Guard(Func<Task> action,string text){try{await action();Message="Saved";}catch(Exception e){log.LogError(e,text);Message=text;}} } }
